CREATE TABLE "public"."blocked_user" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "blocked_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "blocked_user"     bigint,
  "user_who_blocked" bigint,
  CONSTRAINT "blocked_user_blocked_user_key" UNIQUE (blocked_user),
  CONSTRAINT "blocked_user_pkey" PRIMARY KEY (id),
  CONSTRAINT "blocked_user_user_who_blocked_key" UNIQUE (user_who_blocked)
);

ALTER TABLE "public"."blocked_user"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."chat" (
  "id"        bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "circle_id" bigint,
  "event_id"  bigint,
  "friend_id" bigint,
  CONSTRAINT "chat_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."chat"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."circle_member" (
  "id"            bigint                   NOT NULL,
  "user_id"       bigint                   NOT NULL,
  "circle_id"     bigint                   NOT NULL,
  "created_at"    timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text),
  "user_nickname" text,
  CONSTRAINT "circle_member_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."circle_member"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."circle" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "owner_id"   bigint                   NOT NULL,
  CONSTRAINT "circle_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."circle"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."event_invitation" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."invitation_id_seq") NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "accepted"   boolean,
  "user_id"    bigint                   NOT NULL,
  "event_id"   bigint                   NOT NULL,
  CONSTRAINT "invitation_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."event_invitation"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."event" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "owner_id"     bigint                   NOT NULL,
  "scheduled_at" timestamp with time zone NOT NULL,
  "location"     text                     NOT NULL,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "name"         text                     NOT NULL,
  "emoji_icon"   text                     NOT NULL,
  "color"        text                     NOT NULL DEFAULT '#F26419'::text,
  "is_public"    boolean                  NOT NULL,
  CONSTRAINT "event_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."event"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."friend" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "friends_since" timestamp with time zone NOT NULL DEFAULT now(),
  "user_id_1"     bigint                   NOT NULL,
  "user_id_2"     bigint                   NOT NULL,
  CONSTRAINT "friend_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."friend"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."message" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "image"      text,
  "content"    text,
  "sender_id"  bigint                   NOT NULL,
  "chat_id"    bigint,
  CONSTRAINT "message_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."message"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "birthdate"       date                     NOT NULL,
  "username"        text                     NOT NULL,
  "name"            text                     NOT NULL,
  "surname"         text                     NOT NULL,
  "city"            text                     NOT NULL,
  "email"           text                     NOT NULL,
  "hash_password"   text                     NOT NULL,
  "profile_picture" text,
  "private_account" boolean                  NOT NULL DEFAULT false,
  CONSTRAINT "user_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."user"
  ENABLE ROW LEVEL SECURITY;

